local function _decodeAndRun()
	local _xor = (bit32 and bit32.bxor)
	if not _xor then
		local tab = {}
		for i = 0, 255 do
			tab[i] = {}
			for j = 0, 255 do
				local res, p = 0, 1
				local a, b = i, j
				while a > 0 or b > 0 do
					local b1 = a % 2
					local b2 = b % 2
					if b1 ~= b2 then res = res + p end
					a = math.floor(a / 2)
					b = math.floor(b / 2)
					p = p * 2
				end
				tab[i][j] = res
			end
		end
		_xor = function(a, b) return tab[a][b] end
	end

	local fullB64 = table.concat(_payloadChunks)
	local out = {}
	local batch = {}
	local batchCount = 0
	local outCount = 0
	local buf, bits = 0, 0
	local byteIdx = 0

	for i = 1, #fullB64 do
		local c = fullB64:byte(i)
		if c ~= 61 then
			local val = _b64lookup[c]
			if val then
				buf = buf * 64 + val
				bits = bits + 6
				if bits >= 8 then
					bits = bits - 8
					local encByte = math.floor(buf / (2 ^ bits)) % 256
					buf = buf % (2 ^ bits)
					local k = _key:byte((byteIdx % _klen) + 1)
					local salt = (byteIdx * 7 + 13) % 256
					local decByte = _xor(_xor(encByte, k), salt)
					batchCount = batchCount + 1
					batch[batchCount] = string.char(decByte)
					if batchCount >= 4096 then
						outCount = outCount + 1
						out[outCount] = table.concat(batch)
						batchCount = 0
					end
					byteIdx = byteIdx + 1
				end
			end
		end
	end

	if batchCount > 0 then
		outCount = outCount + 1
		local rest = {}
		for j = 1, batchCount do rest[j] = batch[j] end
		out[outCount] = table.concat(rest)
	end

	local decryptedSrc = table.concat(out)
	table.clear(out)
	table.clear(batch)
	table.clear(_payloadChunks)

	local loader = loadstring or load
	local chunk, err = loader(decryptedSrc)
	if not chunk then
		error("[Senden Hub] Failed to compile decrypted module: " .. tostring(err), 2)
	end

	return chunk()
end

return _decodeAndRun()
